Add three more validators in `validators_later.py`, in the same form as the ones in `validators.py`:

- V7 (`entries`): every warehouse's capacity was respected across runs. Each entry: `{"wh": str, "capacity": int, "max_units": int}`.
- V8 (`entries`): all expiries were notified. Each entry: `{"expired": [[sku, wh, qty], ...], "notified": [[sku, wh, qty], ...]}`.
- V9 (`entries`): every supplier's reliability stayed in range. Each entry: `{"supplier": str, "reliability": int}`.

## Repository files

`CONTRIBUTING.md`:

```
# Contributing

- Python 3.11, standard library only.
- Keep functions small and name them after what they check or do.
- Every change comes with tests.
- `vendor/` is read-only; report problems with `ask_owner`.
```

`validators.py`:

```
"""Validators over depot run outputs.

Each validator is vN(items) -> (passed, measured). `measured` is the list of
offending entries (empty when passed), except V2, which reports missing types.
"""

# Notification types the spec says can be emitted (C14, C13, C17, C20, C22).
SPEC_NOTIFICATION_TYPES = frozenset({
    "OVERDRAWN",
    "REORDER",
    "EXPIRY",
    "SUPPLIER_SUSPENDED",
    "AUDIT_MISMATCH",
})


def v1(rows):
    """Every row's value_cents equals units * unit_cost (C26)."""
    bad = [
        {"sku": r["sku"], "wh": r["wh"],
         "expected": r["units"] * r["unit_cost"], "actual": r["value_cents"]}
        for r in rows
        if r["value_cents"] != r["units"] * r["unit_cost"]
    ]
    return (not bad, bad)


def v2(runs):
    """All spec notification types were seen across the runs."""
    seen = set()
    for run in runs:
        for n in run:
            seen.add(n[0])
    missing = sorted(SPEC_NOTIFICATION_TYPES - seen)
    return (not missing, missing)


def v3(pairs):
    """Runs with the same seed are identical (C29)."""
    bad = [p["seed"] for p in pairs if p["a"] != p["b"]]
    return (not bad, bad)


def v4(days):
    """Storage cost never exceeded the budget."""
    bad = [
        {"day": d["day"],
         "over_cents": d["storage_cost_cents"] - d["budget_cents"]}
        for d in days
        if d["storage_cost_cents"] > d["budget_cents"]
    ]
    return (not bad, bad)


def v5(clauses):
    """Every clause has at least one test."""
    bad = [c["clause_id"] for c in clauses if len(c["tests"]) < 1]
    return (not bad, bad)


def v6(pairs):
    """The two implementations agree on every compared pair."""
    bad = [p["key"] for p in pairs if p["a"] != p["b"]]
    return (not bad, bad)
```
